        # always search in "std" domain
        results.extend(self._resolve_ref_xref(env, fromdocname, builder, 'ref',
                                              target, node, contnode))
        results.extend(self._resolve_obj_xref(env, fromdocname, builder, 'any',
                                              target, node, contnode))
        return results

    def _resolve_ref_xref(self, env: "BuildEnvironment", fromdocname: str, builder: "Builder",
                          typ: str, target: str, node: pending_xref, contnode: Element) -> Element:
        if node['refexplicit']:
            # reference to anonymous label; the reference uses
            # the supplied link caption.
            docname, labelid = self.data['anonlabels'].get(target, ('', ''))
            sectname = node.astext()
        else:
            # reference to named label; the final node will
            # contain the section name after the link.
            docname, labelid, sectname = self.data['labels'].get(target, ('', '', ''))
        if not docname:
            return None

        newnode = nodes.reference('', '', internal=True)
        if node['refexplicit']:
            # the reference is explicit, so we just use the given text
            newnode.append(contnode)
        else:
